// PRIVATE authoring corpus. Cases and grade rubrics are original, uncalibrated proposals.
// Primary public publications establish topic provenance, not ownership of our questions.
const grades = ['Intern', 'Junior', 'Middle', 'Senior', 'Lead'];
const rows = [];
function F(group, slug, title, prompt, dimensions, variants, sources, alternatives, errors, practical = true) {
  const levels = Object.fromEntries(grades.map((grade, index) => {
    const [task, actions] = variants[index];
    const answers = actions.split('|');
    if (answers.length !== dimensions.length) throw new Error(`Invalid ProductManagement rubric: ${slug}/${grade}`);
    const criteria = dimensions.map(([skill, , extension], i) => ({
      id: `criterion-${i + 1}`,
      // Middle has an authored cross-family skill mapping. Do not silently
      // assign its narrower skill to an easier or differently scoped action.
      ...(grade === 'Middle' ? { skillId: `ProductManagement:${group}:${skill}` } : {}),
      label: answers[i].replace(/\.$/u, ''),
      missing: `Не рассматривает необходимое действие: ${answers[i]}`,
      partial: `Называет действие, но не выполняет его полностью либо не обосновывает условиями задачи: ${answers[i]}`,
      meets: answers[i],
      strong: `${answers[i]} Показывает конкретный пример или контрпример из исходного кейса; дополнительно: ${extension}`,
    }));
    return [grade, { task: `${task} Обоснуйте решение данными кейса и явно укажите неопределённость.`, expected: answers.join(' '), criteria }];
  }));
  rows.push({ id: `open-product-${slug}`, specialization: 'ProductManagement', group, title, prompt,
    practical, answerFormat: 'text', language: null, sourceIds: sources.map(id => `product-${id}`),
    tags: [slug, group.toLowerCase(), practical ? 'practical-artifact' : 'reasoning'],
    referenceAnswer: levels.Middle.expected, acceptableAlternatives: alternatives, criticalErrors: errors,
    criteria: levels.Middle.criteria, levels,
    personalization: { allowed: ['domain', 'entityNames'], invariants: [
      'Сохранить исходные наблюдения, сегменты, числа, неопределённость и ограничения решения.',
      'Сохранить действие грейда, проверяемые критерии, альтернативы и критические ошибки.',
      'Компания и роли в кейсе синтетические; опыт кандидата меняет контекст, но не даёт баллов.',
    ] },
  });
}

